export const GRAY: [number, number, number, number] = [0.45, 0.45, 0.45, 1];

function makeScene(world: World): void {
    const ambient = world.resource(GlobalAmbientLight);
    ambient.color = 0xffffff;
    ambient.brightness = 400;

    const sun = world.create();
    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 1, -2, -0.35) });
    world.add(sun, DirectionalLight, { color: 0xffffff, illuminance: 6000, shadowMapsEnabled: 1 });

    const camera = world.create();
    world.add(camera, Camera, { clearColor: 0x191816 });
    world.add(camera, StandardRenderer);
    world.add(camera, Orbit, { distance: 14, yaw: 0.7, pitch: 0.3 });
    world.add(camera, Transform);
    world.storage(Orbit).pan.set(camera, 0, 2.5, 0);

    // A unit box hull, sized per entity by its Transform scale; the default mesh is the matching unit cube.
    const box = world.resource(Hulls).add({ name: "box", halfExtents: [0.5, 0.5, 0.5] });
    const materials = world.resource(Materials);

    const floor = world.create();
    world.add(floor, Transform, { translation: [0, FLOOR_TOP - 0.25, 0], scale: [12, 0.5, 12] });
    world.add(floor, Body, { type: BodyType.Static });
    world.add(floor, Shape, { geometry: box });
    world.add(floor, MeshInstance);
    world.add(
        floor,
        MeshMaterial,
        materials.add(StandardMaterial({ baseColor: GRAY, perceptualRoughness: 0.85 })),
    );
    world.add(floor, Floor);

    const cube = world.create();
    world.add(cube, Transform, {
        translation: [0, BOX_START_HEIGHT, 0],
        scale: [BOX_SIZE, BOX_SIZE, BOX_SIZE],
    });
    world.add(cube, Body, { type: BodyType.Dynamic });
    world.add(cube, Shape, { geometry: box });
    world.add(cube, MeshInstance);
    world.add(
        cube,
        MeshMaterial,
        materials.add(StandardMaterial({ baseColor: BLUE, perceptualRoughness: 0.4 })),
    );
    world.add(cube, FallingBox);
}

export const FallingBoxScene: Plugin = {
    name: "FallingBox",
    components: [FallingBox, Floor],
    dependencies: [StandardPhysicsPlugin, OrbitPlugin],
    initialize: makeScene,
};
