import { expect, setDefaultTimeout, test } from "bun:test";
import { createApp, GlobalTransform, Materials, MeshMaterial } from "@dylanebert/shallot";
import { isAwake } from "@dylanebert/shallot/standard/physics";
import { TIMEOUT } from "@dylanebert/shallot/testing";
import {
    BLUE,
    BOX_SIZE,
    BOX_START_HEIGHT,
    FallingBox,
    FallingBoxScene,
    FLOOR_TOP,
    Floor,
    GRAY,
} from "./index";

setDefaultTimeout(TIMEOUT.node);

test("the blue box falls under gravity, lands on the gray floor and comes to rest", async () => {
    const app = await createApp({ defaults: false, plugins: [FallingBoxScene] });
    try {
        const world = app.world;
        const [box] = world.query([FallingBox]);
        const [floor] = world.query([Floor]);
        expect(box).toBeDefined();
        expect(floor).toBeDefined();

        const materials = world.resource(Materials);
        const color = (eid: number) =>
            Array.from(materials.get(world.storage(MeshMaterial).handle.get(eid))!.baseColor);
        expect(color(box!)).toEqual(BLUE.map(Math.fround));
        expect(color(floor!)).toEqual(GRAY.map(Math.fround));

        const y = () => world.storage(GlobalTransform).translation.y.get(box!);
        world.tick();
        const heights = [y()];
        for (let i = 0; i < 30; i++) {
            world.tick();
            heights.push(y());
        }
        // Falling and accelerating: each drop is larger than the previous one.
        expect(heights.at(-1)!).toBeLessThan(BOX_START_HEIGHT - 1);
        const drop = (i: number) => heights[i - 1]! - heights[i]!;
        expect(drop(30)).toBeGreaterThan(drop(5));

        let ticks = 0;
        for (; ticks < 1200 && isAwake(world, box!); ticks++) world.tick();
        expect(isAwake(world, box!)).toBe(false);
        expect(y()).toBeCloseTo(FLOOR_TOP + BOX_SIZE / 2, 1);
    } finally {
        app.dispose();
    }
});
