import { pipelineWarnings, TIMEOUT } from "@dylanebert/shallot/testing";
import { expect, type Page, test } from "playwright/test";

test.use(pipelineWarnings);

/** Blue-dominant pixel count and their mean row, from a screenshot of the canvas. */
async function blue(page: Page, name: string) {
    const shot = await page.locator("#canvas").screenshot();
    if (process.env.SHALLOT_CAPTURE_DIR)
        await Bun.write(`${process.env.SHALLOT_CAPTURE_DIR}/${name}.png`, shot);
    return page.evaluate(async (base64) => {
        const image = await createImageBitmap(
            new Blob([Uint8Array.from(atob(base64), (c) => c.charCodeAt(0))]),
        );
        const canvas = new OffscreenCanvas(image.width, image.height);
        const context = canvas.getContext("2d")!;
        context.drawImage(image, 0, 0);
        const pixels = context.getImageData(0, 0, image.width, image.height).data;
        let count = 0;
        let rows = 0;
        let gray = 0;
        for (let i = 0; i < pixels.length; i += 4) {
            const [r, g, b] = [pixels[i]!, pixels[i + 1]!, pixels[i + 2]!];
            if (b > 60 && b > r * 1.6 && b > g * 1.3) {
                count++;
                rows += Math.floor(i / 4 / image.width);
            } else if (r > 50 && Math.abs(r - g) < 12 && Math.abs(g - b) < 12) gray++;
        }
        return { count, row: count ? rows / count / image.height : -1, gray };
    }, shot.toString("base64"));
}

test("the blue box drops onto the gray floor on its own", async ({ page }) => {
    await page.goto("/");
    await expect(page.locator("body > [data-shallot-loading]")).toHaveCount(0, {
        timeout: TIMEOUT.browser,
    });
    await expect.poll(async () => (await blue(page, "start")).count).toBeGreaterThan(50);
    const start = await blue(page, "start");
    await page.waitForTimeout(4000);
    const rest = await blue(page, "rest");
    expect(rest.count).toBeGreaterThan(50);
    expect(rest.gray, "gray floor visible").toBeGreaterThan(1000);
    expect(rest.row - start.row, "box moved down the frame").toBeGreaterThan(0.1);
    await page.waitForTimeout(1000);
    const later = await blue(page, "later");
    expect(Math.abs(later.row - rest.row), "box stays at rest").toBeLessThan(0.01);
});
